import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../store/farm_store.dart';

class TransactionsScreen extends StatefulWidget { const TransactionsScreen({super.key, required this.type}); final TransactionType? type; @override State<TransactionsScreen> createState() => _TransactionsScreenState(); }
class _TransactionsScreenState extends State<TransactionsScreen> { String query = ''; @override Widget build(BuildContext context) { final store = context.watch<FarmStore>(); final data = store.transactions.where((x) => (widget.type == null || x.type == widget.type) && '${x.category} ${x.description}'.toLowerCase().contains(query.toLowerCase())).toList(); final title = widget.type == TransactionType.income ? store.t('الإيرادات', 'Income') : widget.type == TransactionType.expense ? store.t('المصروفات', 'Expenses') : store.t('كل الحركات', 'All transactions'); return Padding(padding: const EdgeInsets.all(24), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Row(children: [Expanded(child: Text(title, style: Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight: FontWeight.bold))), FilledButton.icon(onPressed: () => _form(context), icon: const Icon(Icons.add), label: Text(store.t('إضافة عملية', 'Add transaction')))]), const SizedBox(height: 18), TextField(onChanged: (v) => setState(() => query = v), decoration: InputDecoration(prefixIcon: const Icon(Icons.search), hintText: store.t('ابحث بالوصف أو التصنيف...', 'Search description or category...'))), const SizedBox(height: 12), Expanded(child: data.isEmpty ? Center(child: Text(store.t('لا توجد عمليات', 'No transactions found'))) : ListView.separated(itemCount: data.length, separatorBuilder: (_, __) => const Divider(), itemBuilder: (_, i) { final x = data[i]; return ListTile(leading: CircleAvatar(child: Icon(x.type == TransactionType.income ? Icons.arrow_upward : Icons.arrow_downward)), title: Text(x.category), subtitle: Text('${x.description} • ${x.date.year}/${x.date.month}/${x.date.day}'), trailing: Wrap(children: [Text('${x.amount.toStringAsFixed(0)} ج.م', style: const TextStyle(fontWeight: FontWeight.bold)), IconButton(icon: const Icon(Icons.delete_outline), onPressed: () => store.remove(x.id))])); }))])); }
Future<void> _form(BuildContext context) async { final store = context.read<FarmStore>(); final desc = TextEditingController(); final amount = TextEditingController(); final category = TextEditingController(); final type = widget.type ?? TransactionType.expense; await showDialog(context: context, builder: (_) => AlertDialog(title: Text(store.t(type == TransactionType.income ? 'إضافة إيراد' : 'إضافة مصروف', type == TransactionType.income ? 'Add income' : 'Add expense')), content: SizedBox(width: 420, child: Column(mainAxisSize: MainAxisSize.min, children: [TextField(controller: category, decoration: InputDecoration(labelText: store.t('التصنيف', 'Category'))), const SizedBox(height: 12), TextField(controller: desc, decoration: InputDecoration(labelText: store.t('الوصف', 'Description'))), const SizedBox(height: 12), TextField(controller: amount, keyboardType: TextInputType.number, decoration: InputDecoration(labelText: store.t('المبلغ', 'Amount')))])), actions: [TextButton(onPressed: () => Navigator.pop(context), child: Text(store.t('إلغاء', 'Cancel'))), FilledButton(onPressed: () { final value = double.tryParse(amount.text); if (category.text.trim().isEmpty || value == null) return; store.add(FarmTransaction(id: DateTime.now().microsecondsSinceEpoch.toString(), type: type, category: category.text.trim(), description: desc.text.trim(), amount: value, date: DateTime.now())); Navigator.pop(context); }, child: Text(store.t('حفظ', 'Save')))])); }
}
